import {ChartCard} from '@github-ui/chart-card'
import {getTickPositions, tooltipFormatter} from './utils/Utility'
import ChartErrorState from './ChartErrorState'

interface AreaChartData {
  id: string
  label: string
  startDate: string
  endDate: string
  value: number
}

interface AreaChartPayload {
  startDate: string
  endDate: string
  data: AreaChartData[]
}

interface AreaChartProps {
  payload: AreaChartPayload
  title: string
  color?: string
  description?: string
  yAxisTitle?: string
}

function AreaChart({payload, title, color, description, yAxisTitle}: AreaChartProps) {
  if (!payload.data || payload.data.length === 0) {
    return <ChartErrorState title={title} description={description} />
  }

  const series = [
    {
      name: title,
      data: payload.data.map(item => [new Date(item.endDate).getTime(), item.value]),
      type: 'area',
      color: color ?? '',
    },
  ]

  return (
    <div className="height-full">
      <ChartCard size="medium" border padding="normal" visibleControls={false} className="width-full height-full">
        <ChartCard.Title as="h2">{title}</ChartCard.Title>
        {description && <ChartCard.Description>{description}</ChartCard.Description>}
        <ChartCard.Chart
          useUTC
          xAxisTitle=""
          yAxisTitle={yAxisTitle ?? ''}
          series={series}
          plotOptions={{
            area: {
              marker: {
                enabled: false,
              },
            },
          }}
          xAxisOptions={{
            type: 'datetime',
            lineWidth: 1,
            gridLineWidth: 1,
            gridLineDashStyle: 'Solid',
            labels: {
              format: '{value:%b %d}',
            },
            minPadding: 0,
            maxPadding: 0,
            tickPositions: getTickPositions(payload.data, 'half'),
          }}
          yAxisOptions={{
            min: 0,
            gridLineWidth: 1,
            gridLineDashStyle: 'Solid',
          }}
          overrideOptionsNotRecommended={{
            chart: {
              spacingRight: 2,
            },
          }}
          tooltipOptions={{
            shared: true,
            formatter: tooltipFormatter((yAxisTitle ?? '').toLowerCase()),
            useHTML: true,
          }}
          type="area"
        />
      </ChartCard>
    </div>
  )
}

export default AreaChart

try{ AreaChart.displayName ||= 'AreaChart' } catch {}