import {DownloadIcon, FileCodeIcon} from '@primer/octicons-react'
import {Button, IconButton} from '@primer/react'
import {SimpleListView} from '@github-ui/simple-list-view'
import {SimpleListItem} from '@github-ui/simple-list-view/SimpleListItem'
import {SimpleListHeader} from '@github-ui/simple-list-view/SimpleListHeader'
import {Dialog} from '@primer/react/experimental'
import {useState, useCallback} from 'react'
import {reactFetchJSON} from '@github-ui/verified-fetch'
import {useClickAnalytics} from '@github-ui/use-analytics'

interface ExportFile {
  name: string
  url: string
}

interface ExportDialogProps {
  slug: string
  exportFiles?: ExportFile[]
  businessId: number
  exportFilesUrl?: string
  downloadFile?: (url: string) => void
  disableExport: boolean
}

const EMPTY_EXPORT_FILES: ExportFile[] = []

const defaultDownloadFile = (url: string) => {
  const link = document.createElement('a')
  link.href = url
  link.download = ''
  link.rel = 'noopener noreferrer'
  document.body.appendChild(link)
  link.click()
  document.body.removeChild(link)
}

export function ExportDialog({
  slug: slug,
  exportFiles: initialExportFiles = EMPTY_EXPORT_FILES,
  businessId,
  exportFilesUrl,
  downloadFile,
  disableExport,
}: ExportDialogProps) {
  const [isOpen, setIsOpen] = useState(false)
  const [exportFiles, setExportFiles] = useState<ExportFile[]>(initialExportFiles)
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const {sendClickAnalyticsEvent} = useClickAnalytics()

  // Memoize the download function to prevent unnecessary re-renders
  const memoizedDownloadFile = useCallback(
    (url: string) => {
      const fn = downloadFile || defaultDownloadFile
      fn(url)
    },
    [downloadFile],
  )

  const fetchExportFiles = useCallback(async () => {
    if (exportFiles.length > 0) {
      // If we already have export files, don't fetch again
      return exportFiles
    }

    setIsLoading(true)
    setError(null)

    try {
      // Use the provided exportFilesUrl, fall back to the hardcoded path (ensures backward compatibility for github-ui)
      const url = exportFilesUrl || `/enterprises/${slug}/insights/copilot/export`
      const response = await reactFetchJSON(url)

      if (!response.ok) {
        throw new Error('Failed to fetch export files')
      }

      const data = await response.json()
      const fetchedFiles = data.export_files || []
      setExportFiles(fetchedFiles)
      return fetchedFiles
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to fetch export files'
      setError(errorMessage)
      return []
    } finally {
      setIsLoading(false)
    }
  }, [slug, exportFiles, exportFilesUrl])

  const handleExportClick = useCallback(async () => {
    const files = await fetchExportFiles()

    if (error || files.length === 0) {
      return
    }

    if (files.length === 1) {
      if (files[0]?.url) {
        // Single file download
        sendClickAnalyticsEvent({
          category: 'copilot_metrics_usage_enterprise_dashboard',
          action: 'export_download_click',
          label: `business_id:${businessId}`,
        })
        memoizedDownloadFile(files[0].url)
      }
    } else {
      setIsOpen(true)
    }
  }, [fetchExportFiles, error, businessId, sendClickAnalyticsEvent, memoizedDownloadFile])

  const handleDialogDownload = (url: string) => {
    // Dialog file download
    sendClickAnalyticsEvent({
      category: 'copilot_metrics_usage_enterprise_dashboard',
      action: 'export_dialog_download_click',
      label: `business_id:${businessId}`,
    })
    memoizedDownloadFile(url)
  }

  const onDialogClose = useCallback(() => setIsOpen(false), [])

  return (
    <div>
      <IconButton
        size="medium"
        variant="default"
        aria-label="Export JSON"
        data-testid="export-json-button"
        icon={DownloadIcon}
        className="d-none d-lg-flex"
        onClick={handleExportClick}
        loading={isLoading}
        disabled={disableExport}
      />
      <Button
        block
        leadingVisual={<DownloadIcon size="small" />}
        size="medium"
        variant="default"
        aria-label="Export JSON"
        data-testid="export-json-icon"
        className="d-flex d-lg-none"
        onClick={handleExportClick}
        loading={isLoading}
        disabled={disableExport}
      >
        Export JSON
      </Button>
      {error && (
        <div className="flash flash-error mt-2" data-testid="export-error">
          {error}
        </div>
      )}
      {isOpen && (
        <Dialog
          title="Export JSON"
          onClose={onDialogClose}
          subtitle="Multi-file export of Copilot usage breakdown in JSON format"
        >
          <Dialog.Body className="p-0 m-0">
            <SimpleListView>
              <SimpleListHeader>
                <SimpleListHeader.Title
                  headingLevel="h2"
                  className="fgColor-muted"
                  style={{fontSize: 'var(--text-title-shorthand-small)'}}
                  data-testid="export-json-dialog"
                >
                  {exportFiles.length} files
                </SimpleListHeader.Title>
              </SimpleListHeader>
              <SimpleListView.Items>
                {exportFiles.map(item => (
                  <SimpleListItem key={item.name}>
                    <div className="hide-sm mr-2 d-flex flex-items-center">
                      <FileCodeIcon />
                    </div>
                    <SimpleListItem.Title>
                      <span className="wb-break-word">{item.name}</span>
                    </SimpleListItem.Title>
                    <SimpleListItem.Actions>
                      <Button onClick={() => handleDialogDownload(item.url)}>
                        <span className="hide-sm">Download</span>
                        <DownloadIcon className="hide-md hide-lg hide-xl" />
                      </Button>
                    </SimpleListItem.Actions>
                  </SimpleListItem>
                ))}
              </SimpleListView.Items>
            </SimpleListView>
          </Dialog.Body>
        </Dialog>
      )}
    </div>
  )
}

try{ ExportDialog.displayName ||= 'ExportDialog' } catch {}