import {ChartCard} from '@github-ui/chart-card'
import {getTickPositions, tooltipFormatter} from './utils/Utility'
import ChartErrorState from './ChartErrorState'

interface MultipleSeriesLineChartData {
  id: string
  label: string
  startDate: string
  endDate: string
  values: Array<{
    name: string
    value: number
  }>
}

interface MultipleSeriesLineChartPayload {
  startDate: string
  endDate: string
  data: MultipleSeriesLineChartData[]
}

interface MultipleSeriesLineChartProps {
  payload: MultipleSeriesLineChartPayload
  title: string
  description?: string
  yAxisTitle?: string
  chartWidth?: 'half' | 'full'
}

const lineColors = [
  'var(--Segment-3, var(--display-purple-scale-4))',
  'var(--Segment-1, var(--display-purple-scale-8))',
]
const lineStyles = ['ShortDash', 'Solid']

function MultipleSeriesLineChart({
  payload,
  title,
  description,
  yAxisTitle,
  chartWidth = 'half',
}: MultipleSeriesLineChartProps) {
  if (!payload.data || payload.data.length === 0) {
    return <ChartErrorState title={title} description={description} />
  }

  const seriesNames = payload.data[0]?.values?.map(v => v.name) || []
  const series = seriesNames.map(seriesName => ({
    name: seriesName,
    data: payload.data.map(item => {
      const seriesData = item.values.find(v => v.name === seriesName)
      const value = seriesData?.value ?? 0
      return [new Date(item.endDate).getTime(), value]
    }),
    type: 'line',
    color: lineColors[seriesNames.indexOf(seriesName) % lineColors.length],
    dashStyle: lineStyles[seriesNames.indexOf(seriesName) % lineStyles.length],
  }))

  return (
    <div className="height-full">
      <ChartCard size="medium" border padding="normal" visibleControls={false} className="width-full height-full">
        <ChartCard.Title as="h2">{title}</ChartCard.Title>
        {description && <ChartCard.Description>{description}</ChartCard.Description>}
        <ChartCard.Chart
          useUTC
          xAxisTitle=""
          yAxisTitle={yAxisTitle ?? ''}
          series={series}
          plotOptions={{
            line: {
              marker: {
                enabled: false,
              },
            },
          }}
          xAxisOptions={{
            type: 'datetime',
            lineWidth: 1,
            gridLineWidth: 1,
            gridLineDashStyle: 'Solid',
            labels: {
              format: '{value:%b %d}',
            },
            minPadding: 0,
            maxPadding: 0,
            tickPositions: getTickPositions(payload.data, chartWidth),
          }}
          yAxisOptions={{
            min: 0,
            gridLineWidth: 1,
            gridLineDashStyle: 'Solid',
          }}
          tooltipOptions={{
            shared: true,
            formatter: tooltipFormatter(yAxisTitle?.toLowerCase()),
            useHTML: true,
          }}
          overrideOptionsNotRecommended={{
            legend: {
              reversed: true,
            },
          }}
          type="line"
        />
      </ChartCard>
    </div>
  )
}

export default MultipleSeriesLineChart

try{ MultipleSeriesLineChart.displayName ||= 'MultipleSeriesLineChart' } catch {}