import {useEffect} from 'react'
import {useSearchParams} from '@github-ui/use-navigate'

type CanonicalQueryParams = {
  period: string
  interval: string
}

const ALLOWED_PERIODS = new Set(['7d', '14d', '28d'])
const ALLOWED_INTERVALS = new Set(['1d'])

export function useQuerySanitizer({period: canonicalPeriod, interval: canonicalInterval}: CanonicalQueryParams) {
  const [, setSearchParams] = useSearchParams()

  useEffect(() => {
    setSearchParams(
      params => {
        for (const [key] of params.entries()) {
          if (key !== 'period' && key !== 'interval') {
            params.delete(key)
          }
        }

        const currentPeriod = params.get('period')
        if (!currentPeriod || !ALLOWED_PERIODS.has(currentPeriod)) {
          params.set('period', canonicalPeriod)
        }

        const currentInterval = params.get('interval')
        if (!currentInterval || !ALLOWED_INTERVALS.has(currentInterval)) {
          params.set('interval', canonicalInterval)
        }

        return params
      },
      {replace: true, preventAutofocus: true},
    )
  }, [setSearchParams, canonicalPeriod, canonicalInterval])
}

try{ ALLOWED_PERIODS.displayName ||= 'ALLOWED_PERIODS' } catch {}
try{ ALLOWED_INTERVALS.displayName ||= 'ALLOWED_INTERVALS' } catch {}