import {ChartCard} from '@github-ui/chart-card'
import {getTickPositions, tooltipFormatter} from './utils/Utility'
import ChartErrorState from './ChartErrorState'

interface ColumnChartData {
  id: string
  label: string
  startDate?: string
  endDate?: string
  values: {
    [key: string]: number
  }
}

interface ColumnChartPayload {
  startDate?: string
  endDate?: string
  data: ColumnChartData[]
}

interface ColumnChartProps {
  payload: ColumnChartPayload
  title: string
  description?: string
  xAxisTitle?: string
  yAxisTitle?: string
  columnColours?: string[]
  yAxisOptions?: Record<string, unknown>
  chartWidth?: 'half' | 'full'
  stacked?: boolean
}

function ColumnChart({
  payload,
  title,
  description,
  xAxisTitle,
  yAxisTitle,
  columnColours,
  yAxisOptions,
  chartWidth = 'full',
  stacked = false,
}: ColumnChartProps) {
  if (!payload.data || payload.data.length === 0) {
    return <ChartErrorState title={title} description={description} />
  }

  const {series, hasDateValues, categories} = computeChartData(payload, columnColours)

  return (
    <div className="height-full">
      <ChartCard size="medium" border padding="normal" visibleControls={false} className="width-full">
        <ChartCard.Title as="h2">{title}</ChartCard.Title>
        {description && <ChartCard.Description>{description}</ChartCard.Description>}
        <ChartCard.Chart
          useUTC
          xAxisTitle={xAxisTitle ?? ''}
          yAxisTitle={yAxisTitle ?? ''}
          series={series}
          xAxisOptions={{
            gridLineWidth: 0,
            ...(hasDateValues ? {labels: {format: '{value:%b %d}'}} : {}),
            minPadding: 0,
            maxPadding: 0,
            ...(hasDateValues ? {type: 'datetime'} : {type: 'category', categories}),
            ...(hasDateValues ? {tickPositions: getTickPositions(payload.data, chartWidth)} : {}),
          }}
          yAxisOptions={{
            min: 0,
            ...yAxisOptions,
          }}
          type="column"
          plotOptions={{
            column: {
              pointPadding: 0.05,
              groupPadding: 0.05,
              borderWidth: 0,
              borderRadius: 0,
              ...(stacked && {stacking: 'normal'}),
            },
          }}
          tooltipOptions={{
            shared: true,
            useHTML: true,
            formatter: tooltipFormatter(yAxisTitle?.toLowerCase()),
          }}
          overrideOptionsNotRecommended={{
            // Prevent accessibility related landmarks issues by ensuring unique element roles
            accessibility: {
              landmarkVerbosity: 'one',
              series: {
                describeSingleSeries: true,
              },
            },
            legend: {
              align: 'left',
              verticalAlign: 'top',
              layout: 'horizontal',
              reversed: false,
              alignColumns: false,
            },
          }}
        />
      </ChartCard>
    </div>
  )
}

function computeChartData(payload: ColumnChartPayload, columnColours?: string[]) {
  const hasDateValues = payload.data.some(d => d.endDate)
  const categories = !hasDateValues ? payload.data.map(d => d.label) : []
  const metrics = Object.keys(payload.data[0]?.values ?? [])

  const series = [...metrics].map(metric => ({
    name: metric,
    data: hasDateValues
      ? payload.data.map(d => [new Date(d.endDate ?? d.startDate ?? 0).getTime(), d.values?.[metric] ?? 0])
      : payload.data.map(d => d.values?.[metric] ?? 0),
    type: 'column',
    color: columnColours?.[metrics.indexOf(metric)],
  }))

  return {series, hasDateValues, categories}
}

export default ColumnChart

try{ ColumnChart.displayName ||= 'ColumnChart' } catch {}