import {registerDataRouterApp} from '@github-ui/react-core/register-app'
import {copilotInsightsUsageAppBuilder} from './config/app-builder'

import {copilotUsageRoute, stafftoolsCopilotUsageRoute} from './routes/copilot-usage-route'
import {copilotMetricsDailyActiveUsersRoute} from './routes/copilot-metrics-route'
import {copilotCodeGenerationRoute} from './routes/copilot-code-generation-route'
import {CopilotUsage} from './routes/CopilotUsage'
import {CopilotMetrics} from './routes/CopilotMetrics'
import {CopilotCodeGeneration} from './routes/CopilotCodeGeneration'

export const copilotInsightsUsageApp = copilotInsightsUsageAppBuilder.createDataRouterAppFromRoutes([
  copilotUsageRoute.toRoute({Component: CopilotUsage}),
  stafftoolsCopilotUsageRoute.toRoute({Component: CopilotUsage}),
  copilotMetricsDailyActiveUsersRoute.toRoute({Component: CopilotMetrics}),
  copilotCodeGenerationRoute.toRoute({Component: CopilotCodeGeneration}),
])
registerDataRouterApp(copilotInsightsUsageApp)
