import {copilotInsightsUsageAppBuilder} from '../config/app-builder'

const createCopilotMetricsRoute = (name: string, endpoint: string, queries: [] | undefined) =>
  copilotInsightsUsageAppBuilder.createQueryRouteConfig(`copilotMetrics${name}Route`, {
    path: `/enterprises/:slug/insights/copilot/metrics/${endpoint}`,
    queries,
  })

export type CopilotMetricsDailyActiveUsersResponse = {}
export const copilotMetricsDailyActiveUsersRoute = createCopilotMetricsRoute(
  'DailyActiveUsers',
  'daily-active-users',
  [],
)
