import {copilotInsightsUsageAppBuilder} from '../config/app-builder'
import {mainQuery} from '@github-ui/react-core/future/main-query'
import type {CodeGenerationMetricCardsPayload, LineChartPayload, MultiColumnChartPayload} from '../types/chart-types'

export type CopilotCodeGenerationRouteResponse = {
  codeGenerationMetrics: {
    linesOfCodeAcceptanceRate: LineChartPayload
    linesOfCodePerDay: MultiColumnChartPayload
    linesOfCodePerLanguage: MultiColumnChartPayload
    linesOfCodePerMode: MultiColumnChartPayload
    linesOfCodePerModel: MultiColumnChartPayload
    metricCardsData: CodeGenerationMetricCardsPayload
  }
  slug: string
  copilotLicenseManagementLink: string
  displayBlankslate: boolean
  displayError: boolean
  exportFilesUrl: string
  businessId: number
  canonicalQueryParams: {
    period: string
    interval: string
  }
}

export const copilotCodeGenerationRoute = copilotInsightsUsageAppBuilder.createQueryRouteConfig(
  'copilotCodeGenerationRoute',
  {
    path: '/enterprises/:slug/insights/copilot/code-generation',
    queries: [
      mainQuery<CopilotCodeGenerationRouteResponse>({
        queryDeps: ({pathname, searchParams}) => ({
          pathname,
          searchParams: {
            period: searchParams.get('period') || '7d',
          },
        }),
      }),
    ],
  },
)
