import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {Stack} from '@primer/react'
import {copilotCodeGenerationRoute} from './copilot-code-generation-route'
import ColumnChart from '../components/charts/ColumnChart'
import {blueShades, indigoShades, orangeShades, purpleShades} from '../components/charts/utils/chart-colors'
import AreaChart from '../components/charts/AreaChart'
import {clsx} from 'clsx'
import styles from '../styles/CopilotUsage.module.css'
import {useQuerySanitizer} from '../hooks/useQuerySanitizer'
import {Header} from '../components/header/Header'
import MetricCards from '../components/metric-cards/MetricCards'
import {CopilotBlankslate} from '../components/CopilotBlankslate'

export function CopilotCodeGeneration() {
  const payload = useRouteQuery(copilotCodeGenerationRoute, 'mainQuery')
  const {
    codeGenerationMetrics,
    copilotLicenseManagementLink,
    displayBlankslate,
    displayError,
    exportFilesUrl,
    slug,
    businessId,
    canonicalQueryParams,
  } = payload?.data ?? {}

  useQuerySanitizer(canonicalQueryParams)

  const renderCopilotGenerationCharts = () => {
    if (displayBlankslate) {
      return (
        <CopilotBlankslate
          type="welcome"
          dashboardType="code-generation"
          copilotLicenseManagementLink={copilotLicenseManagementLink}
          testId="copilot-code-generation-blankslate"
        />
      )
    } else if (displayError) {
      return (
        <CopilotBlankslate
          type="error"
          dashboardType="code-generation"
          copilotLicenseManagementLink={copilotLicenseManagementLink}
          testId="copilot-code-generation-error"
        />
      )
    }

    const metricCardsData = codeGenerationMetrics.metricCardsData.data

    return (
      <div className="flex-xl-row flex-column width-xl-auto width-full">
        <Stack direction="horizontal" wrap="wrap" className="gap-3">
          <Stack.Item grow>
            <MetricCards
              cards={[
                {
                  title: 'Avg suggested lines of code per active user',
                  value: metricCardsData.averageSuggestedLinesCardData,
                  description:
                    'Including suggested additions and deletions across all modes in the current calendar month',
                },
                {
                  title: 'Avg accepted lines of code per active user',
                  value: metricCardsData.averageAcceptedLinesCardData,
                  description:
                    'Including accepted additions and deletions across all modes in the current calendar month',
                },
                {
                  title: 'Acceptance rate per active user',
                  value: metricCardsData.acceptanceRateCardData,
                  description:
                    'Percentage of additions and deletions accepted across all modes in the current calendar month',
                },
              ]}
            />
          </Stack.Item>
          <Stack.Item grow className="width-full">
            <ColumnChart
              payload={codeGenerationMetrics.linesOfCodePerDay}
              title="Lines of code per day"
              description="Daily trends in the volume of suggested and accepted lines of code, including additions and deletions, across all modes"
              yAxisTitle="Lines of code"
              chartWidth="full"
              columnColours={indigoShades}
            />
          </Stack.Item>
          <Stack.Item grow className="width-full">
            <AreaChart
              payload={codeGenerationMetrics.linesOfCodeAcceptanceRate}
              title="Lines of code acceptance rate"
              description="Percentage of suggested additions and deletions accepted across all modes, indicating overall adoption and engagement"
              yAxisTitle="%"
              color="#30A147"
            />
          </Stack.Item>
          <Stack.Item grow className="width-full">
            <ColumnChart
              payload={codeGenerationMetrics.linesOfCodePerMode}
              title="Lines of code per mode"
              description="Compares the volume of lines of code suggested and accepted by users across all modes, with deletions only applicable in agent modes"
              yAxisTitle="Lines of code"
              chartWidth="full"
              columnColours={purpleShades}
            />
          </Stack.Item>
          <Stack.Item grow className="width-full">
            <div className="d-flex flex-column flex-xl-row gap-3 width-full flex-xl-items-stretch">
              <div className="flex-1 min-width-0 d-flex flex-column">
                <ColumnChart
                  payload={codeGenerationMetrics.linesOfCodePerModel}
                  title="Lines of code per model"
                  description="Compares models by the volume of lines of code suggested and accepted by users, for both additions and deletions"
                  yAxisTitle="Lines of code"
                  chartWidth="half"
                  columnColours={blueShades}
                />
              </div>
              <div className="flex-1 min-width-0 d-flex flex-column">
                <ColumnChart
                  payload={codeGenerationMetrics.linesOfCodePerLanguage}
                  title="Lines of code per language"
                  description="Compares languages by the volume of code suggested and accepted by users, for both additions and deletions"
                  yAxisTitle="Lines of code"
                  chartWidth="half"
                  columnColours={orangeShades}
                />
              </div>
            </div>
          </Stack.Item>
        </Stack>
      </div>
    )
  }

  return (
    <div data-testid="copilot-code-generation" className="d-flex flex-column gap-3">
      <hr className={clsx('d-md-none mt-0 mb-0', styles.CopilotUsagePageDivider)} />
      <Header title={'IDE code generation'} slug={slug} businessId={businessId} exportFilesUrl={exportFilesUrl} />
      {renderCopilotGenerationCharts()}
    </div>
  )
}

try{ CopilotCodeGeneration.displayName ||= 'CopilotCodeGeneration' } catch {}