import Highcharts from 'highcharts'
import styles from '../../../styles/CopilotUsage.module.css'

interface TickPositionData {
  endDate?: string
  startDate?: string
}

type ChartWidth = 'half' | 'full'

export function getTickPositions(data: TickPositionData[], chartWidth: ChartWidth): number[] {
  if (data.length === 0) {
    return []
  }

  const allPositions = data
    .map(item => new Date(item.endDate || item.startDate || '').getTime())
    .filter(timestamp => timestamp > 0)

  if (allPositions.length === 0) {
    return []
  }

  if (allPositions.length <= 7 || (chartWidth === 'full' && allPositions.length <= 14)) {
    return allPositions
  }

  if (chartWidth === 'half') {
    if (allPositions.length <= 14) {
      return allPositions.filter((_, i) => i % 2 === 0 && i < allPositions.length - 1)
    }
    return [
      allPositions[0] ?? 0,
      allPositions[6] ?? 0,
      allPositions[13] ?? 0,
      allPositions[20] ?? 0,
      allPositions[27] ?? 0,
    ]
  }

  return allPositions.filter((_, i) => i % 2 === 0)
}

export function formatTooltipHeader(value?: string | number): string {
  if (typeof value === 'number') {
    return Highcharts.dateFormat('%A, %b %e, %Y', value)
  } else if (typeof value === 'string') {
    return value
  } else {
    return ''
  }
}

function formatValueWithUnit(value?: number | null, unit?: string): string {
  if (value === null || value === undefined || Number.isNaN(value)) return '-'

  const formattedValue = value.toLocaleString()

  return unit?.trim() === '%' ? `${formattedValue}%` : `${formattedValue} ${unit ?? ''}`.trim()
}

export function tooltipFormatter(unit?: string) {
  return function (this: Highcharts.TooltipFormatterContextObject): string {
    if (!this.points) return ''

    let tooltipBody = ''

    const xFormatted = formatTooltipHeader(this.x)

    // eslint-disable-next-line github/unescaped-html-literal
    tooltipBody += `<div class="${styles.CopilotUsageChartTooltipHeader}">${xFormatted}</div>`

    const tooltipData = this.points.map(point => {
      const valueWithUnit = formatValueWithUnit(point.y, unit)

      return `
        <div class="${styles.CopilotUsageChartTooltipDataPoint}">
          <div>
            <span style="color:${point.color}; padding-right: 4px">\u25CF</span>
            <span style="padding-right: 8px">${point.series.name}</span>
          </div>
          <span><b>${valueWithUnit}</b></span>
        </div>
      `
    })

    // eslint-disable-next-line github/unescaped-html-literal
    tooltipBody += tooltipData.join('<br/>')

    // eslint-disable-next-line github/unescaped-html-literal
    return `<div>${tooltipBody}</div>`
  }
}
