import {ActionList, ActionMenu} from '@primer/react'
import {useSearchParams} from '@github-ui/use-navigate'
import {CalendarIcon} from '@primer/octicons-react'
import styles from '../../styles/PeriodFilter.module.css'

const periods = [
  {label: 'Last 7 days', value: '7d'},
  {label: 'Last 14 days', value: '14d'},
  {label: 'Last 28 days', value: '28d'},
]

const PeriodFilter = () => {
  const [searchParams, setSearchParams] = useSearchParams()
  const currentPeriod = searchParams.get('period')
  const showButtonLabel = periods.find(p => p.value === currentPeriod)?.label ?? 'Last 28 days'

  return (
    <ActionMenu>
      <ActionMenu.Button block leadingVisual={<CalendarIcon />} className={styles.buttonContent}>
        <span>{showButtonLabel}</span>
      </ActionMenu.Button>
      <ActionMenu.Overlay
        variant={{
          narrow: 'fullscreen',
        }}
      >
        <ActionList selectionVariant="single" aria-label="Period Filter">
          {periods.map(period => (
            <ActionList.Item
              key={period.value}
              selected={period.value === currentPeriod}
              onSelect={() =>
                setSearchParams(
                  prev => {
                    const next = new URLSearchParams(prev)
                    next.set('period', period.value)
                    return next
                  },
                  {preventAutofocus: true},
                )
              }
            >
              {period.label}
            </ActionList.Item>
          ))}
        </ActionList>
      </ActionMenu.Overlay>
    </ActionMenu>
  )
}

export default PeriodFilter

try{ PeriodFilter.displayName ||= 'PeriodFilter' } catch {}