import type {DonutChartPayload} from '../components/charts/DonutChart'
import {copilotInsightsUsageAppBuilder} from '../config/app-builder'
import {mainQuery} from '@github-ui/react-core/future/main-query'
import type {
  StackedColumnChartPayload,
  LineChartPayload,
  UsageMetricCardsPayload,
  StackedAreaChartPayload,
  MultipleSeriesChartPayload,
} from '../types/chart-types'

export type CopilotUsageRouteResponse = {
  copilotLicenseManagementLink: string
  exportFilesUrl: string
  displayBlankslate: boolean
  displayError: boolean
  usageMetrics: {
    averageRequestsPerActiveChatUser: LineChartPayload
    dailyActiveUsers: LineChartPayload
    weeklyActiveUsers: LineChartPayload
    metricCardsData: UsageMetricCardsPayload
    requestsPerFeature: StackedColumnChartPayload
    modelUsage: DonutChartPayload
    codeCompletionsAcceptanceRate: LineChartPayload
    modelUsagePerFeature: StackedColumnChartPayload
    modelUsagePerDay: StackedAreaChartPayload
    codeCompletions: MultipleSeriesChartPayload
    languageUsage: DonutChartPayload
    languageUsagePerDay: StackedAreaChartPayload
    modelUsagePerLanguage: StackedColumnChartPayload
  }
  slug: string
  businessId: number
  canonicalQueryParams: {
    period: string
    interval: string
  }
}

export const periodMap: Record<string, string> = {
  '7d': '7 days',
  '14d': '14 days',
  '28d': '28 days',
}

// stafftools version of the route
export const stafftoolsCopilotUsageRoute = copilotInsightsUsageAppBuilder.createQueryRouteConfig(
  'stafftoolsCopilotUsageRoute',
  {
    path: '/stafftools/enterprises/:slug/copilot_insights_usage',
    queries: [
      mainQuery<CopilotUsageRouteResponse>({
        queryDeps: ({pathname, searchParams}) => ({
          pathname,
          searchParams: {
            period: searchParams.get('period') || '7d',
          },
        }),
      }),
    ],
  },
)

// customer-facing version of the route
export const copilotUsageRoute = copilotInsightsUsageAppBuilder.createQueryRouteConfig('copilotUsageRoute', {
  path: '/enterprises/:slug/insights/copilot',
  queries: [
    mainQuery<CopilotUsageRouteResponse>({
      queryDeps: ({pathname, searchParams}) => ({
        pathname,
        searchParams: {
          period: searchParams.get('period') || '7d',
        },
      }),
    }),
  ],
})
