import {ChartCard} from '@github-ui/chart-card'
import {getTickPositions, tooltipFormatter} from './utils/Utility'
import ChartErrorState from './ChartErrorState'

interface LineChartData {
  id: string
  label: string
  startDate: string
  endDate: string
  value: number
}

interface LineChartPayload {
  startDate: string
  endDate: string
  data: LineChartData[]
}

interface LineChartProps {
  payload: LineChartPayload
  title: string
  description?: string
  yAxisTitle?: string
  chartWidth?: 'half' | 'full'
}

function LineChart({payload, title, description, yAxisTitle, chartWidth = 'full'}: LineChartProps) {
  if (!payload.data || payload.data.length === 0) {
    return <ChartErrorState title={title} description={description} />
  }

  const series = [
    {
      name: title,
      data: payload.data.map(item => [new Date(item.endDate).getTime(), item.value]),
      type: 'line',
      color: '#30A147',
    },
  ]

  return (
    <div className="height-full">
      <ChartCard size="medium" border padding="normal" visibleControls={false} className="width-full height-full">
        <ChartCard.Title as="h2">{title}</ChartCard.Title>
        {description && <ChartCard.Description>{description}</ChartCard.Description>}
        <ChartCard.Chart
          useUTC
          xAxisTitle=""
          yAxisTitle={yAxisTitle ?? ''}
          series={series}
          plotOptions={{
            line: {
              marker: {
                enabled: false,
              },
            },
          }}
          xAxisOptions={{
            type: 'datetime',
            lineWidth: 1,
            gridLineWidth: 1,
            gridLineDashStyle: 'Solid',
            labels: {
              format: '{value:%b %d}',
            },
            minPadding: 0,
            maxPadding: 0,
            tickPositions: getTickPositions(payload.data, chartWidth),
          }}
          yAxisOptions={{
            min: 0,
            gridLineWidth: 1,
            gridLineDashStyle: 'Solid',
          }}
          tooltipOptions={{
            shared: true,
            formatter: tooltipFormatter(yAxisTitle?.toLowerCase()),
          }}
          type="line"
        />
      </ChartCard>
    </div>
  )
}

export default LineChart

try{ LineChart.displayName ||= 'LineChart' } catch {}